<?php
namespace App\Http\Controllers\Crm;
use App\Http\Controllers\Controller;use App\Models\{Customer,Reminder};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class DashboardController extends Controller {public function index(Request $r){$u=$r->user();$from=$r->date('from')??now()->startOfMonth();$to=$r->date('to')??now();$scope=fn($q,$col='branch_id')=>$u->isCeo()?$q:$q->where($col,$u->branch_id);$customersByBranch=$scope(Customer::whereBetween('created_at',[$from,$to]))->select('branch_id',DB::raw('count(*) as total'))->groupBy('branch_id')->with('branch:id,name')->get();$baruCount=$scope(Customer::whereBetween('created_at',[$from,$to]))->count();$repeatCount=$scope(Customer::query())->has('purchases','>=',2)->count();$vip=$scope(Customer::query())->withSum(['purchases'=>fn($q)=>$q->whereBetween('purchased_at',[$from,$to])],'total_amount')->orderByDesc('purchases_sum_total_amount')->limit(20)->get();$repeatProducts=DB::table('purchase_items')->join('purchases','purchases.id','=','purchase_items.purchase_id')->when(!$u->isCeo(),fn($q)=>$q->where('purchases.branch_id',$u->branch_id))->whereBetween('purchases.purchased_at',[$from,$to])->select('purchase_items.product_name',DB::raw('count(distinct purchases.customer_id) as pembeli_unik'),DB::raw('count(*) as total_dibeli'))->groupBy('purchase_items.product_name')->havingRaw('count(*) > count(distinct purchases.customer_id)')->orderByDesc('total_dibeli')->limit(20)->get();$reminderStats=Reminder::query()->when(!$u->isCeo(),fn($q)=>$q->whereHas('purchase',fn($p)=>$p->where('branch_id',$u->branch_id)))->whereBetween('due_date',[$from,$to])->select('stage','status',DB::raw('count(*) as total'))->groupBy('stage','status')->get()->groupBy('stage');return view('crm.dashboard',compact('customersByBranch','baruCount','repeatCount','vip','repeatProducts','reminderStats','from','to'));}}
